import Link from "next/link";
import { ProductPhoto } from "@/components/ProductPhoto";
import { ResumeList } from "@/components/ResumeList";
import { Waveform } from "@/components/voice/VoiceControls";
import { formatPrice } from "@/lib/format";
import { catalogExample } from "@/lib/retail/catalog";
import { RETAILER_LABELS } from "@/lib/types";
import { isVoiceConfigured } from "@/lib/voice/settings";

const EXAMPLES = [
  { kind: "zip swaddle newborn", name: "Zip swaddle", reason: "Zips beat velcro and folding at 3am." },
  { kind: "bassinet", name: "Bassinet", reason: "Keeps baby within arm's reach for the first months." },
  { kind: "baby nasal aspirator", name: "Nasal aspirator", reason: "A stuffy newborn can't feed well. This clears it fast." },
];

export default function Home() {
  const examples = EXAMPLES.flatMap((example) => {
    const offer = catalogExample(example.kind);
    return offer ? [{ ...example, offer }] : [];
  });

  return (
    <main className="pt-6 lg:pt-10">
      <p className="font-serif text-[17px] font-semibold">Calm Registry</p>

      <div className="mt-8">
        <ResumeList />
      </div>

      <div className="mt-14 grid grid-cols-[minmax(0,1fr)] gap-16 lg:mt-20 lg:grid-cols-[1.15fr_1fr] lg:items-center lg:gap-20">
        <section className="space-y-6">
          <h1 className="max-w-[16ch] font-serif text-[41px] leading-[1.1] font-semibold sm:text-[52px] lg:text-[56px] lg:leading-[1.05] xl:text-[64px] 2xl:text-[76px]">
            A baby registry you can finish tonight
          </h1>
          <p className="max-w-[46ch] text-[17px] text-muted lg:text-[19px]">
            Talk or type through a few questions. You get a complete registry of real products from Amazon, Target, and Walmart, with
            a note on why each one is there. Then review it one category at a time.
          </p>
          <Link href="/start" className="btn-primary w-full text-[17px] sm:w-auto sm:px-8">
            Start my registry
          </Link>
        </section>

        {examples.length > 0 && (
          <section aria-labelledby="examples" className="space-y-5 lg:rounded-2xl lg:bg-surface lg:p-8">
            <h2 id="examples" className="font-serif text-[21px] font-semibold">
              Every item comes with a reason
            </h2>
            <ul className="space-y-6 md:grid md:grid-cols-3 md:gap-6 md:space-y-0 lg:block lg:space-y-6">
              {examples.map(({ name, reason, offer }) => (
                <li key={name} className="flex gap-4 md:flex-col lg:flex-row">
                  <ProductPhoto offer={offer} label={name} className="h-24 w-24 md:aspect-square md:h-auto md:w-full lg:h-24 lg:w-24" />
                  <div className="min-w-0 space-y-1">
                    <p className="font-semibold">{name}</p>
                    <p className="font-serif text-[15px] leading-snug text-note italic">{reason}</p>
                    <p className="truncate text-[13px] text-muted">{offer.title}</p>
                    <p className="text-[13px] text-muted tabular-nums">
                      {formatPrice(offer.price)} at {RETAILER_LABELS[offer.retailer]}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </section>
        )}
      </div>

      {isVoiceConfigured() && (
        <section
          aria-labelledby="voice"
          className="mt-20 rounded-[28px] bg-room px-6 py-10 text-room-text sm:px-10 lg:mt-28 lg:grid lg:grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)] lg:items-center lg:gap-16 lg:px-14 lg:py-16"
        >
          <div className="space-y-4">
            <h2 id="voice" className="max-w-[18ch] font-serif text-[30px] leading-tight font-semibold lg:text-[42px] lg:leading-[1.1]">
              Talk it through instead of typing
            </h2>
            <p className="max-w-[44ch] text-room-muted lg:text-[17px]">
              Tap the mic and answer out loud, the way you would tell a friend. Later, say what has changed and the
              registry updates once you agree.
            </p>
          </div>
          <div className="mt-10 lg:mt-0">
            <Waveform className="h-20 w-full text-wave sm:h-24 lg:h-32" />
            <p className="mt-6 font-serif text-[19px] leading-relaxed lg:text-[22px]">
              Do you have a car, or will you mostly be walking?
            </p>
            <p className="mt-2 text-[14px] text-room-muted">You said: Mostly walking. We&rsquo;re on the third floor.</p>
          </div>
        </section>
      )}

      <section aria-labelledby="how" className="mt-20 space-y-5 lg:mt-28">
        <h2 id="how" className="font-serif text-[21px] font-semibold">
          How it works
        </h2>
        <ol className="grid gap-4 lg:grid-cols-3 lg:gap-10">
          {[
            "Talk or type for a few minutes about your space, budget, and plans.",
            "Review your draft one category at a time. Keep or skip each item.",
            "Share one link. Family buys from whichever store they like and marks it as gifted.",
          ].map((step, i) => (
            <li key={step} className="flex gap-4 lg:border-t lg:border-line lg:pt-5">
              <span className="w-4 shrink-0 font-serif text-[17px] text-accent">{i + 1}</span>
              <span>{step}</span>
            </li>
          ))}
        </ol>
      </section>

    </main>
  );
}
"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { AnswersCard } from "@/components/AnswersCard";
import { AuthGate } from "@/components/AuthGate";
import { Building } from "@/components/Building";
import { useVoiceAgent, useVoiceEnabled } from "@/components/voice/useVoiceAgent";
import { TalkButton, VoiceInvite, VoiceRoom } from "@/components/voice/VoiceControls";
import { api } from "@/lib/client";
import { normalizeProfile } from "@/lib/profile";
import { ParentProfileSchema, type ChatMessage, type IntakeDraft, type ParentProfile } from "@/lib/types";

type Turn = { reply: string; chips: string[]; done: boolean; profile: ParentProfile | null };

/** Where answers lived before they were saved to the account; moved into a draft once. */
const LEGACY_STORAGE_KEY = "calm-registry:intake";
const TOTAL_QUESTIONS = 9;

export default function StartPage() {
  return (
    <AuthGate reason="Sign in with your email first so your registry is saved. No password needed.">
      <IntakeChat />
    </AuthGate>
  );
}

/** Opens the draft named in the URL, or the one for ?registry= (starting over), ?from= (reusing answers), or ?new. */
async function openDraft(): Promise<IntakeDraft> {
  const params = new URLSearchParams(window.location.search);
  const draftId = params.get("draft");
  if (draftId) {
    const found = await api<{ draft: IntakeDraft }>(`/api/drafts/${draftId}`).catch(() => null);
    if (found) return found.draft;
  }
  const registryId = params.get("registry");
  const from = params.get("from");
  const body = registryId ? { registryId } : from ? { seedFrom: from } : { fresh: params.has("new") };
  return (await api<{ draft: IntakeDraft }>("/api/drafts", { method: "POST", body: JSON.stringify(body) })).draft;
}

function IntakeChat() {
  const router = useRouter();
  const [draft, setDraft] = useState<IntakeDraft | null>(null);
  const [registryTitle, setRegistryTitle] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chips, setChips] = useState<string[]>([]);
  const [profile, setProfile] = useState<ParentProfile | null>(null);
  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);
  const [building, setBuilding] = useState(false);
  const [confirmRestart, setConfirmRestart] = useState(false);
  const [editing, setEditing] = useState<{ index: number; text: string } | null>(null);
  const [error, setError] = useState("");
  const bottom = useRef<HTMLDivElement>(null);
  const loaded = useRef(false);
  const voiceEnabled = useVoiceEnabled();
  const voice = useVoiceAgent({
    onText(role, content, isGreeting) {
      // The greeting repeats a question that's already on screen.
      if (!isGreeting) setMessages((prev) => [...prev, { role, content }]);
    },
    async onFunction(name, args) {
      if (name !== "finish_intake") return `Unknown function ${name}.`;
      // Names are optional, so a missing one shouldn't send the agent back to ask again.
      const parsed = ParentProfileSchema.safeParse({ parentNames: "", babyName: "", ...args });
      if (!parsed.success) {
        const fields = [...new Set(parsed.error.issues.map((i) => i.path.join(".") || "profile"))].join(", ");
        return `The profile isn't complete. Problems with: ${fields}. Ask about those, then call finish_intake again.`;
      }
      voice.stopAfterSpeaking();
      setChips([]);
      setProfile(normalizeProfile(parsed.data));
      return "Success. Their answers are on screen for them to check before building.";
    },
    onError: setError,
  });

  useEffect(() => {
    void (async () => {
      try {
        const opened = await openDraft();
        let { messages, chips } = opened;
        const legacy = localStorage.getItem(LEGACY_STORAGE_KEY);
        if (legacy && !messages.length && !opened.registryId && !opened.seed) {
          ({ messages, chips } = JSON.parse(legacy) as { messages: ChatMessage[]; chips: string[] });
        }
        localStorage.removeItem(LEGACY_STORAGE_KEY);
        router.replace(`/start?draft=${opened.id}`);
        setDraft(opened);
        setMessages(messages);
        setChips(chips);
        setProfile(opened.profile);
        loaded.current = true;
        if (opened.registryId) {
          const { registry } = await api<{ registry: { title: string } }>(`/api/registries/${opened.registryId}`);
          setRegistryTitle(registry.title);
        }
        if (!messages.length) await send([], opened);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Your answers couldn't be loaded.");
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Saved to the account shortly after each change, so leaving midway never loses answers.
  useEffect(() => {
    if (!draft || !loaded.current) return;
    const timer = setTimeout(() => {
      // Building or cancelling deletes the draft; a save landing after that would fail.
      if (!loaded.current) return;
      void api(`/api/drafts/${draft.id}`, { method: "PUT", body: JSON.stringify({ messages, chips, profile }) }).catch(() => undefined);
    }, 400);
    return () => clearTimeout(timer);
  }, [draft, messages, chips, profile]);

  useEffect(() => {
    bottom.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, chips, thinking, profile]);

  async function send(history: ChatMessage[], current = draft) {
    setThinking(true);
    setError("");
    try {
      const turn = await api<Turn>("/api/intake", {
        method: "POST",
        body: JSON.stringify({ messages: history, seed: current?.seed ?? undefined }),
      });
      setMessages([...history, { role: "assistant" as const, content: turn.reply }]);
      setChips(turn.done ? [] : turn.chips);
      if (turn.done && turn.profile) setProfile(turn.profile);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong.");
    } finally {
      setThinking(false);
    }
  }

  async function build() {
    if (!profile || !draft) return;
    voice.stop();
    loaded.current = false;
    setBuilding(true);
    try {
      const { id } = await api<{ id: string }>("/api/registries", {
        method: "POST",
        body: JSON.stringify({ profile, draftId: draft.id, registryId: draft.registryId ?? undefined }),
      });
      router.push(`/registry/${id}/review`);
    } catch (e) {
      loaded.current = true;
      setBuilding(false);
      setError(e instanceof Error ? e.message : "Your registry couldn't be built. Try again.");
    }
  }

  function answer(text: string) {
    const trimmed = text.trim();
    if (!trimmed || thinking) return;
    const history = [...messages, { role: "user" as const, content: trimmed }];
    setMessages(history);
    setChips([]);
    setInput("");
    void send(history);
  }

  /** Changing an earlier answer drops everything after it, so the chat picks up from there. */
  function saveEdit() {
    if (!editing || thinking) return;
    const text = editing.text.trim();
    if (!text) return;
    voice.stop();
    const history = [...messages.slice(0, editing.index), { role: "user" as const, content: text }];
    setEditing(null);
    setProfile(null);
    setMessages(history);
    setChips([]);
    void send(history);
  }

  function talk() {
    setError("");
    setChips([]);
    void voice.start({ mode: "intake", messages, seed: draft?.seed ?? undefined });
  }

  function restart() {
    voice.stop();
    setConfirmRestart(false);
    setEditing(null);
    setProfile(null);
    setMessages([]);
    setChips([]);
    void send([]);
  }

  async function cancelStartOver() {
    if (!draft?.registryId) return;
    voice.stop();
    loaded.current = false;
    await api(`/api/drafts/${draft.id}`, { method: "DELETE" }).catch(() => undefined);
    router.push(`/registry/${draft.registryId}`);
  }

  if (building) return <Building />;

  const answered = messages.filter((m) => m.role === "user").length;
  const lastAnswer = messages.findLastIndex((m) => m.role === "user");
  const left = TOTAL_QUESTIONS - Object.keys(draft?.seed ?? {}).length - answered;

  return (
    <div className="lg:grid lg:grid-cols-[220px_minmax(0,1fr)] lg:gap-16">
    <IntakeGuide answered={answered} />
    <div className="flex min-h-dvh flex-col pt-5 lg:pt-10">
      <header className="mb-8 space-y-2 text-[13px]">
        {draft?.registryId && (
          <div className="flex items-center justify-between gap-4">
            <span className="min-w-0 truncate">Starting over: {registryTitle || "your registry"}</span>
            <button onClick={() => void cancelStartOver()} className="link shrink-0">
              Keep my current list
            </button>
          </div>
        )}
        {confirmRestart ? (
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-surface px-4 py-3" role="alert">
            <span>Clear all your answers and start again?</span>
            <span className="flex gap-2">
              <button className="btn-quiet px-3 py-1.5 text-[13px]" onClick={() => setConfirmRestart(false)}>
                Keep them
              </button>
              <button className="btn-primary px-3 py-1.5 text-[13px]" onClick={restart}>
                Clear answers
              </button>
            </span>
          </div>
        ) : (
          <div className="flex items-center justify-between">
            <span className="text-muted">
              {profile ? "Check your answers" : left > 1 ? `About ${left} questions left` : "Almost done"}
            </span>
            {answered > 0 && (
              <button onClick={() => setConfirmRestart(true)} className="link">
                Start over
              </button>
            )}
          </div>
        )}
      </header>

      <div className="flex-1 space-y-6" aria-live="polite">
        {messages.map((m, i) =>
          m.role === "user" ? (
            <div key={i} className="flex flex-col items-end gap-1">
              {editing?.index === i ? (
                <form
                  className="w-full max-w-[80%] space-y-2 lg:max-w-[60%]"
                  onSubmit={(e) => {
                    e.preventDefault();
                    saveEdit();
                  }}
                >
                  <label htmlFor="edit-answer" className="sr-only">
                    Change your answer
                  </label>
                  <textarea
                    id="edit-answer"
                    autoFocus
                    rows={2}
                    value={editing.text}
                    onChange={(e) => setEditing({ index: i, text: e.target.value })}
                    className="field resize-none"
                  />
                  <p className="text-[13px] text-muted">The questions after this one will be asked again.</p>
                  <div className="flex justify-end gap-2">
                    <button type="button" className="btn-quiet px-4 py-2" onClick={() => setEditing(null)}>
                      Cancel
                    </button>
                    <button className="btn-primary px-4 py-2" disabled={!editing.text.trim() || thinking}>
                      Save answer
                    </button>
                  </div>
                </form>
              ) : (
                <>
                  <button
                    type="button"
                    disabled={thinking || voice.active}
                    onClick={() => setEditing({ index: i, text: m.content })}
                    aria-label={`Change your answer: ${m.content}`}
                    className="max-w-[80%] rounded-2xl rounded-br-md bg-surface px-4 py-2.5 text-left transition-colors hover:bg-raise lg:max-w-[60%] lg:px-5 lg:py-3 lg:text-[17px]"
                  >
                    {m.content}
                  </button>
                  {i === lastAnswer && !thinking && !voice.active && (
                    <span className="text-[12px] text-muted">Tap any answer to change it</span>
                  )}
                </>
              )}
            </div>
          ) : (
            <p key={i} className="max-w-[65ch] font-serif text-[19px] leading-relaxed lg:text-[22px]">
              {m.content}
            </p>
          ),
        )}
        {thinking && <p className="font-serif text-[19px] text-muted">…</p>}
        {profile && !thinking && (
          <AnswersCard
            profile={profile}
            onChange={setProfile}
            title="Here's what I heard"
            intro="Tap anything that's not quite right. Nothing is built until you say so."
          >
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <button className="link text-left text-[13px]" onClick={() => setProfile(null)}>
                Something missing? Keep chatting
              </button>
              <button className="btn-primary sm:px-8" onClick={() => void build()}>
                {draft?.registryId ? "Rebuild my registry" : "Build my registry"}
              </button>
            </div>
          </AnswersCard>
        )}
        {error && (
          <p role="alert" className="text-[14px] text-danger">
            {error}{" "}
            <button className="underline underline-offset-4" onClick={() => void (profile ? build() : send(messages))}>
              Try again
            </button>
          </p>
        )}
        <div ref={bottom} />
      </div>

      {!profile && (
      <div className="sticky bottom-0 -mx-4 space-y-3 bg-bg px-4 pt-4 pb-[max(1rem,env(safe-area-inset-bottom))] sm:-mx-6 sm:px-6">
        {voice.active ? (
          <VoiceRoom
            status={voice.status}
            muted={voice.muted}
            onMute={voice.setMuted}
            onStop={voice.stop}
            stopLabel="Type instead"
            level={voice.level}
            hint="Talk naturally. You can interrupt, and your answers appear above as you go."
          />
        ) : (
          <>
            {voiceEnabled && answered === 0 && (
              <VoiceInvite
                title="Answer out loud"
                detail="Most people finish in about five minutes. You can switch to typing anytime."
                onStart={talk}
                disabled={thinking || !draft}
              />
            )}
            {chips.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {chips.map((chip) => (
                  <button key={chip} className="chip" onClick={() => answer(chip)} disabled={thinking}>
                    {chip}
                  </button>
                ))}
              </div>
            )}
            <form
              onSubmit={(e) => {
                e.preventDefault();
                answer(input);
              }}
              className="flex gap-2"
            >
              <label htmlFor="chat-input" className="sr-only">
                Your answer
              </label>
              <input
                id="chat-input"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Or type your own answer"
                className="field"
              />
              {voiceEnabled && answered > 0 && !input.trim() ? (
                <TalkButton label="Answer out loud" onClick={talk} disabled={thinking || !draft} />
              ) : (
                <button className="btn-primary shrink-0" disabled={thinking || !input.trim()}>
                  Send
                </button>
              )}
            </form>
          </>
        )}
      </div>
      )}
    </div>
    </div>
  );
}

const TOPICS = [
  "When your baby is due",
  "Your home, and whether you drive",
  "How you plan to feed",
  "Your budget",
  "What matters to you, like eco-friendly or minimal",
  "What you already have",
  "Stores you like",
];
const STEPS = ["Answer a few questions", "Review your draft", "Share with family"];

/** Laptop-only context beside the chat: where you are, and what the questions cover. */
function IntakeGuide({ answered }: { answered: number }) {
  const progress = Math.min(1, answered / 8);
  return (
    <aside className="hidden space-y-10 pt-10 lg:sticky lg:top-0 lg:block lg:self-start">
      <p className="font-serif text-[17px] font-semibold">Calm Registry</p>

      <ol className="space-y-2">
        {STEPS.map((step, i) => (
          <li key={step} className={`flex gap-3 ${i === 0 ? "text-text" : "text-muted"}`}>
            <span className={`w-4 shrink-0 font-serif ${i === 0 ? "text-accent" : ""}`}>{i + 1}</span>
            {step}
          </li>
        ))}
      </ol>

      <div className="space-y-3">
        <div className="h-1 overflow-hidden rounded-full bg-line" aria-hidden>
          <div className="h-full rounded-full bg-accent transition-[width] duration-500" style={{ width: `${progress * 100}%` }} />
        </div>
        <p className="text-[13px] text-muted">The questions cover</p>
        <ul className="space-y-1.5 text-[14px]">
          {TOPICS.map((topic) => (
            <li key={topic}>{topic}</li>
          ))}
        </ul>
      </div>
    </aside>
  );
}
"use client";

import { useEffect, useState } from "react";
import { authEnabled, getBrowserSupabase } from "@/lib/client";
import { Status } from "./Status";

export function AuthGate({ children, reason }: { children: React.ReactNode; reason?: string }) {
  const [state, setState] = useState<"loading" | "in" | "out">(authEnabled ? "loading" : "in");

  useEffect(() => {
    const supabase = getBrowserSupabase();
    if (!supabase) return;
    void supabase.auth.getSession().then(({ data }) => setState(data.session ? "in" : "out"));
    const { data } = supabase.auth.onAuthStateChange((_event, session) => setState(session ? "in" : "out"));
    return () => data.subscription.unsubscribe();
  }, []);

  if (state === "in") return <>{children}</>;
  if (state === "loading") return <Status>One moment…</Status>;
  return <SignIn reason={reason} />;
}

const REASSURANCES = [
  "We email you a one-time sign-in link.",
  "Come back from any device, anytime.",
  "Family and friends never need an account.",
];

export function SignIn({ reason }: { reason?: string }) {
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");

  async function send(event: React.FormEvent) {
    event.preventDefault();
    setError("");
    const supabase = getBrowserSupabase();
    if (!supabase) return setError("Sign-in isn't set up for this site yet.");
    const { error } = await supabase.auth.signInWithOtp({
      email,
      options: { emailRedirectTo: window.location.href },
    });
    if (error) setError(error.message);
    else setSent(true);
  }

  return (
    <main className="grid min-h-dvh content-center gap-12 py-12 lg:grid-cols-2 lg:items-center lg:gap-24">
      <div className="space-y-6">
        <p className="font-serif text-[17px] font-semibold">Calm Registry</p>
        <h1 className="font-serif text-[33px] leading-tight font-semibold lg:text-[52px] lg:leading-[1.08]">
          Save your registry
        </h1>
        <p className="max-w-[44ch] text-muted lg:text-[17px]">
          {reason ?? "Sign in with your email so you can come back to your registry anytime. No password needed."}
        </p>
        <ul className="hidden space-y-2 lg:block">
          {REASSURANCES.map((line) => (
            <li key={line} className="flex gap-3">
              <span aria-hidden className="mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-accent" />
              {line}
            </li>
          ))}
        </ul>
      </div>

      <div className="rounded-2xl bg-surface p-6 lg:p-10">
        {sent ? (
          <div role="status" className="space-y-2">
            <p className="font-serif text-[21px] font-semibold">Check your inbox</p>
            <p className="text-muted">
              We sent a sign-in link to <span className="text-text">{email}</span>. Open it on this device to pick up where
              you left off.
            </p>
          </div>
        ) : (
          <form onSubmit={send} className="space-y-4">
