function ShareRow({ slug }: { slug: string }) {
  const [copied, setCopied] = useState(false);
  const url = typeof window === "undefined" ? `/r/${slug}` : `${window.location.origin}/r/${slug}`;

  async function share() {
    if (navigator.share) {
      await navigator.share({ title: "Our baby registry", url }).catch(() => undefined);
      return;
    }
    await navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="flex items-center justify-between gap-4">
      <div className="min-w-0">
        <p className="font-semibold">Share with family and friends</p>
        <a href={url} target="_blank" rel="noopener noreferrer" className="block truncate text-[13px] text-muted hover:text-text">
          {url.replace(/^https?:\/\//, "")}
        </a>
      </div>
      <button className="btn-quiet shrink-0 px-4 py-2.5" onClick={() => void share()}>
        {copied ? "Link copied" : "Share link"}
      </button>
    </div>
  );
}

const SUGGESTIONS = ["Make it cheaper", "We already have a crib", "More eco-friendly", "Add a baby swing"];

/** Change the registry by describing it, pinned to the bottom of the screen. */
function EditBar({ registry, onApplied }: { registry: Registry; onApplied: () => Promise<void> }) {
  const [text, setText] = useState("");
  const [diff, setDiff] = useState<EditDiff | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [heard, setHeard] = useState<{ role: "user" | "assistant"; content: string } | null>(null);
  // Voice function calls arrive outside React's render cycle, so they read the pending diff from here.
  const diffRef = useRef<EditDiff | null>(null);

  const names = new Map(registry.items.map((i) => [i.id, i.name]));

  function showDiff(next: EditDiff | null) {
    diffRef.current = next;
    setDiff(next);
  }

  async function requestDiff(request: string) {
    const { diff } = await api<{ diff: EditDiff }>(`/api/registries/${registry.id}/edit`, {
      method: "POST",
      body: JSON.stringify({ request }),
    });
    showDiff(diff);
    return diff;
  }

  async function applyDiff(pending: EditDiff) {
    await api(`/api/registries/${registry.id}/edit`, { method: "POST", body: JSON.stringify({ diff: pending }) });
    showDiff(null);
    setText("");
    await onApplied();
  }

  async function run(task: () => Promise<unknown>) {
    setBusy(true);
    setError("");
    try {
      await task();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That change didn't go through. Try again.");
    } finally {
      setBusy(false);
    }
  }

  function propose(request: string) {
    if (request.trim()) void run(() => requestDiff(request));
  }

  function apply() {
    if (diff) void run(() => applyDiff(diff));
  }

  function describe(d: EditDiff) {
    return [
      ...d.remove.map((id) => `remove ${names.get(id)}`),
      ...d.add.map((item) => `add ${item.name}`),
      ...d.swap.map((s) => `find a different ${names.get(s.id)}`),
    ];
  }

  const voiceEnabled = useVoiceEnabled();
  const voice = useVoiceAgent({
    onText: (role, content) => setHeard({ role, content }),
    onError: setError,
    async onFunction(name, args) {
      if (name === "preview_change") {
        const request = String(args.request ?? "").trim();
        if (!request) return "No request was given. Ask what they'd like to change.";
        setBusy(true);
        try {
          const next = await requestDiff(request.slice(0, 500));
          const changes = describe(next);
          return JSON.stringify(
            changes.length
              ? {
                  proposed: changes,
                  summary: next.summary,
                  next: "Nothing has changed yet. Describe the proposal as something you'd do, like \"I'd remove the stroller\", and ask if you should go ahead.",
                }
              : { proposed: [], summary: next.summary, next: "Nothing would change. Tell them, and ask what else they'd like." },
          );
        } finally {
          setBusy(false);
        }
      }
      if (name === "apply_change") {
        const pending = diffRef.current;
        if (!pending || !describe(pending).length) return "There's no change waiting. Call preview_change first.";
        setBusy(true);
        try {
          await applyDiff(pending);
          return "Applied. The registry is updated. Tell them it's done and ask if there's anything else.";
        } finally {
          setBusy(false);
        }
      }
      if (name === "cancel_change") {
        showDiff(null);
        return "Cancelled. Nothing was changed.";
      }
      return `Unknown function ${name}.`;
    },
  });

  function talk() {
    setError("");
    setHeard(null);
    void voice.start({ mode: "edit", registryId: registry.id });
  }

  const hasChanges = diff && (diff.add.length || diff.remove.length || diff.swap.length);

  return (
    <div className="fixed inset-x-0 bottom-0 z-20 border-t border-line bg-bg/95 backdrop-blur lg:static lg:z-auto lg:border-0 lg:bg-transparent lg:backdrop-blur-none">
      <div className="mx-auto max-w-2xl space-y-3 px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-6 lg:max-w-none lg:p-0">
        <p className="hidden font-semibold lg:block">Change your registry</p>
        {diff && (
          <div className="max-h-[45dvh] space-y-3 overflow-y-auto rounded-xl bg-surface p-4">
            <p className="font-serif text-[17px] text-note italic">{diff.summary}</p>
            <ul className="space-y-1 text-[14px]">
              {diff.remove.map((id) => (
                <li key={id}>Remove {names.get(id)}</li>
              ))}
              {diff.add.map((item) => (
                <li key={item.name}>Add {item.name}</li>
              ))}
              {diff.swap.map((s) => (
                <li key={s.id}>Find a different {names.get(s.id)?.toLowerCase()}</li>
              ))}
            </ul>
            <div className="flex gap-2">
              <button className="btn-quiet flex-1 py-2.5" onClick={() => showDiff(null)} disabled={busy}>
                Cancel
              </button>
              {hasChanges ? (
                <button className="btn-primary flex-1 py-2.5" onClick={apply} disabled={busy}>
                  {busy ? "Applying…" : "Apply changes"}
                </button>
              ) : null}
            </div>
          </div>
        )}
        {!voice.active && !diff && !text && (
          <div className="no-scrollbar -mx-4 flex gap-2 overflow-x-auto px-4 sm:-mx-6 sm:px-6 lg:mx-0 lg:flex-wrap lg:overflow-visible lg:px-0">
            {SUGGESTIONS.map((s) => (
              <button
                key={s}
                className="chip shrink-0 py-1.5 text-[13px]"
                disabled={busy}
                onClick={() => {
                  setText(s);
                  propose(s);
                }}
              >
                {s}
              </button>
            ))}
          </div>
        )}
        {error && (
          <p role="alert" className="text-[13px] text-danger">
            {error}
          </p>
        )}
        {voice.active ? (
          <VoiceRoom
            status={voice.status}
            muted={voice.muted}
            onMute={voice.setMuted}
            onStop={voice.stop}
            stopLabel="Done"
            level={voice.level}
            heard={heard}
            hint="Say what's changed, like a hand-me-down stroller or a smaller budget."
          />
        ) : (
          <>
          {voiceEnabled && !diff && (
            <div className="hidden lg:block">
              <VoiceInvite title="Say a change" detail="Tell it what's changed. Nothing updates until you agree." onStart={talk} disabled={busy} />
            </div>
          )}
          <form
            onSubmit={(e) => {
              e.preventDefault();
              propose(text);
            }}
            className="flex gap-2 lg:flex-wrap"
          >
            <label htmlFor="edit-request" className="sr-only">
              Describe a change
            </label>
            <input
              id="edit-request"
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="We're getting a hand-me-down stroller"
              className="field lg:basis-full"
            />
            {voiceEnabled && (
              <div className="shrink-0 lg:hidden">
                <TalkButton label="Say a change out loud" onClick={talk} disabled={busy} />
              </div>
            )}
            <button className="btn-primary shrink-0 lg:flex-1" disabled={busy || !text.trim()}>
              {busy && !diff ? "Thinking…" : "Change"}
            </button>
          </form>
          </>
        )}
      </div>
    </div>
  );
}
"use client";

import Link from "next/link";
import { use, useMemo, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ItemCard } from "@/components/ItemCard";
import { ProductPhoto } from "@/components/ProductPhoto";
import { StartOverLink } from "@/components/RegistryActions";
import { Status } from "@/components/Status";
import { useRegistry } from "@/components/useRegistry";
import { CATEGORIES, type Category } from "@/lib/types";

export default function ReviewPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Review id={id} />
    </AuthGate>
  );
}

type Group = { category: Category; items: unknown[]; pending: Array<{ id: string }> };

function Review({ id }: { id: string }) {
  const { registry, error, setStatus, setPrimary } = useRegistry(id);
  const [category, setCategory] = useState<Category | null>(null);

  const groups = useMemo(() => {
    if (!registry) return [];
    return CATEGORIES.map((c) => {
      const items = registry.items.filter((i) => i.category === c);
      return { category: c, items, pending: items.filter((i) => i.status === "pending") };
    }).filter((g) => g.items.length > 0);
  }, [registry]);

  if (error && !registry) return <Status tone="error">{error}</Status>;
  if (!registry) return <Status>Opening your registry…</Status>;

  const total = registry.items.length;
  const reviewed = registry.items.filter((i) => i.status !== "pending").length;
  const progress = total ? reviewed / total : 0;
  const active = category ? groups.find((g) => g.category === category) : null;
  const current = active?.pending[0];

  const header = (
    <header className="sticky top-0 z-10 -mx-4 space-y-3 bg-bg px-4 pt-5 pb-4 sm:-mx-6 sm:px-6">
      <div className="flex items-center justify-between text-[13px]">
        {active ? (
          <button onClick={() => setCategory(null)} className="link">
            All categories
          </button>
        ) : (
          <Link href={`/registry/${id}`} className="link">
            Registry overview
          </Link>
        )}
        <span className="text-muted tabular-nums">
          {reviewed} of {total} reviewed
        </span>
      </div>
      <div
        className="h-1 overflow-hidden rounded-full bg-line"
        role="progressbar"
        aria-valuenow={reviewed}
        aria-valuemax={total}
        aria-label="Review progress"
      >
        <div className="h-full rounded-full bg-accent transition-[width] duration-500" style={{ width: `${progress * 100}%` }} />
      </div>
    </header>
  );

  if (active) {
    return (
      <main className="space-y-5">
        {header}
        {current && (
          <div className="flex items-baseline justify-between">
            <h1 className="font-serif text-[21px] font-semibold">{active.category}</h1>
            <span className="text-[13px] text-muted tabular-nums">
              {active.items.length - active.pending.length + 1} of {active.items.length}
            </span>
          </div>
        )}

        {current ? (
          <ItemCard key={current.id} item={current} onChooseOffer={(offerId) => void setPrimary(current.id, offerId)}>
            <div className="sticky bottom-0 -mx-4 grid grid-cols-2 gap-3 bg-bg px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:-mx-6 sm:px-6 md:static md:mx-0 md:px-0 md:pt-4 md:pb-0">
              <button className="btn-quiet" onClick={() => void setStatus(current.id, "skip")}>
                Skip
              </button>
              <button className="btn-primary" onClick={() => void setStatus(current.id, "keep")}>
                Keep
              </button>
            </div>
          </ItemCard>
        ) : (
          <div className="space-y-8 pt-6 lg:pt-10">
            <div className="space-y-2">
              <h1 className="font-serif text-[26px] font-semibold lg:text-[41px]">{active.category} is reviewed.</h1>
              <p className="text-muted lg:text-[17px]">
                You kept {active.items.filter((i) => i.status === "keep").length} of {active.items.length} items.
              </p>
            </div>
            <ul className="grid grid-cols-3 gap-3 sm:grid-cols-4 lg:grid-cols-6 lg:gap-5">
              {active.items
                .filter((i) => i.status === "keep")
                .map((item) => (
                  <li key={item.id} className="space-y-2">
                    <ProductPhoto offer={item.offers[0]} label={item.name} className="aspect-square w-full" />
                    <p className="truncate text-[13px]">{item.name}</p>
                  </li>
                ))}
            </ul>
            <div className="sm:max-w-sm">
              <NextStep groups={groups} onPick={setCategory} id={id} />
            </div>
          </div>
        )}
      </main>
    );
  }

  return (
    <main className="space-y-8">
      {header}
      <div className="space-y-3">
        <h1 className="font-serif text-[33px] leading-tight font-semibold lg:text-[48px]">{registry.title}</h1>
        <p className="max-w-[60ch] text-muted lg:text-[17px]">
          Your full draft is ready. Go through it one category at a time, in any order. Stop whenever you like, your
          progress is saved.
        </p>
      </div>

      <ul className="border-t border-line">
        {groups.map((g) => {
          const done = g.pending.length === 0;
          const minutes = Math.max(1, Math.round(g.pending.length / 3));
          return (
            <li key={g.category} className="border-b border-line">
              <button
                onClick={() => setCategory(g.category)}
                className="group flex w-full items-center justify-between gap-6 py-4 text-left lg:py-5"
              >
                <span className="font-serif text-[21px] transition-colors group-hover:text-accent lg:w-48 lg:shrink-0 lg:text-[26px]">
                  {g.category}
                </span>
                <span className="hidden flex-1 gap-3 lg:flex" aria-hidden>
                  {g.items.slice(0, 7).map((item) => (
                    <ProductPhoto
                      key={item.id}
                      offer={item.offers[0]}
                      label=""
                      className={`h-16 w-16 rounded-[10px] ${item.status === "skip" ? "opacity-30" : ""}`}
                    />
                  ))}
                </span>
                <span className="shrink-0 text-[13px] text-muted tabular-nums lg:text-[14px]">
                  {done ? "Reviewed" : `${g.pending.length} to review, about ${minutes} min`}
                </span>
              </button>
            </li>
          );
        })}
      </ul>

      {progress === 1 && (
        <Link href={`/registry/${id}`} className="btn-primary w-full sm:w-auto sm:px-8">
          See and share your registry
        </Link>
      )}

      <div className="sm:max-w-md">
        <StartOverLink registry={registry} label="Not what you wanted? Start over with new answers" />
      </div>
    </main>
  );
}

function NextStep({ groups, onPick, id }: { groups: Group[]; onPick: (c: Category | null) => void; id: string }) {
  const next = groups.find((g) => g.pending.length > 0);
  if (!next) {
    return (
      <Link href={`/registry/${id}`} className="btn-primary w-full">
        See and share your registry
      </Link>
    );
  }
  return (
    <button className="btn-primary w-full" onClick={() => onPick(next.category)}>
      Review {next.category}
    </button>
  );
}
"use client";

import { use, useCallback, useEffect, useState } from "react";
import { AddressAsk } from "@/components/AddressAsk";
import { ProductPhoto } from "@/components/ProductPhoto";
import { ProductRating } from "@/components/ProductRating";
import { Status } from "@/components/Status";
import { formatPrice, getBrowserSupabase } from "@/lib/client";
import { CATEGORIES, RETAILER_LABELS, type Registry, type RegistryItem, type RetailerId } from "@/lib/types";

type PublicRegistry = Omit<Registry, "ownerId" | "profile">;

const POLL_MS = 15000;

export default function SharePage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  return (
    <div data-theme="day">
      <Gifts slug={slug} />
    </div>
  );
}

function Gifts({ slug }: { slug: string }) {
  const [registry, setRegistry] = useState<PublicRegistry | null>(null);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    const response = await fetch(`/api/r/${slug}`, { cache: "no-store" });
    const data = (await response.json()) as { registry?: PublicRegistry; error?: string };
    if (data.registry) setRegistry(data.registry);
    else setError(data.error ?? "This registry link doesn't work. Ask the parents for a new one.");
  }, [slug]);

  useEffect(() => {
    void load();
    // Poll even when realtime is available, so the page still updates if broadcasts are down.
    const timer = setInterval(() => void load(), POLL_MS);
    const supabase = getBrowserSupabase();
    const channel = supabase
      ?.channel(`registry:${slug}`)
      .on("broadcast", { event: "registry_changed" }, () => void load())
      .subscribe();
    return () => {
      clearInterval(timer);
      if (supabase && channel) void supabase.removeChannel(channel);
