    </form>
  );
}

function AddressRequests({
  registryId,
  requests,
  hasAddress,
  onChange,
}: {
  registryId: string;
  requests: AddressRequest[];
  hasAddress: boolean;
  onChange: () => Promise<void>;
}) {
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState("");
  const pending = requests.filter((r) => r.status === "pending");
  const approved = requests.filter((r) => r.status === "approved");

  async function decide(requestId: string, decision: "approved" | "declined") {
    setBusy(requestId);
    setError("");
    try {
      await api(`/api/registries/${registryId}/details`, { method: "POST", body: JSON.stringify({ requestId, decision }) });
      await onChange();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't go through. Try again.");
    } finally {
      setBusy(null);
    }
  }

  if (!pending.length && !approved.length) return null;

  return (
    <div className="space-y-3">
      {pending.length > 0 && (
        <div className="space-y-3 rounded-xl bg-surface p-4">
          <p className="font-semibold">
            {pending.length === 1 ? "1 person is" : `${pending.length} people are`} asking for your address
          </p>
          {!hasAddress && <p className="text-[13px] text-muted">Add an address in your details before sharing it.</p>}
          <ul className="space-y-4">
            {pending.map((r) => (
              <li key={r.id} className="space-y-2">
                <div className="text-[14px]">
                  <p>
                    <span className="font-semibold">{r.name}</span> <span className="text-muted">({r.contact})</span>
                  </p>
                  {r.message && <p className="font-serif text-note italic">&ldquo;{r.message}&rdquo;</p>}
                </div>
                <div className="flex gap-2">
                  <button className="btn-quiet flex-1 py-2" onClick={() => void decide(r.id, "declined")} disabled={busy === r.id}>
                    Decline
                  </button>
                  <button
                    className="btn-primary flex-1 py-2"
                    onClick={() => void decide(r.id, "approved")}
                    disabled={busy === r.id || !hasAddress}
                  >
                    Share address
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
      {approved.length > 0 && (
        <details className="text-[13px] text-muted">
          <summary className="cursor-pointer">Address shared with {approved.length === 1 ? approved[0].name : `${approved.length} people`}</summary>
          <ul className="mt-2 space-y-1">
            {approved.map((r) => (
              <li key={r.id} className="flex items-center justify-between gap-3">
                <span className="truncate">
                  {r.name} ({r.contact})
                </span>
                <button className="link shrink-0" onClick={() => void decide(r.id, "declined")} disabled={busy === r.id}>
                  Stop sharing
                </button>
              </li>
            ))}
          </ul>
        </details>
      )}
      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
    </div>
  );
}
import { RETAILER_LABELS, type Offer } from "@/lib/types";

/** Link a retailer-provided rating to the product page, where shoppers can read the reviews. */
export function ProductRating({ offer, className = "" }: { offer?: Offer; className?: string }) {
  // Older saved catalog offers contain a price-tier estimate, not a customer rating.
  const rating = offer?.externalId.startsWith("catalog:") ? null : offer?.rating;
  if (!offer || offer.externalId.startsWith("search:")) return null;
  const hasRating = rating != null && Number.isFinite(rating) && rating > 0 && rating <= 5;

  const label = hasRating
    ? `${rating.toFixed(1)} out of 5 stars at ${RETAILER_LABELS[offer.retailer]}. Open product page to read reviews`
    : `Open ${RETAILER_LABELS[offer.retailer]} product page to read reviews`;
  return (
    <a
      href={offer.url}
      target="_blank"
      rel="noopener noreferrer sponsored"
      aria-label={label}
      className={`inline-flex w-fit items-center gap-1.5 text-[13px] text-muted hover:text-text ${className}`}
    >
      {hasRating && (
        <span aria-hidden="true" className="relative inline-block whitespace-nowrap tracking-[1px] text-line">
          ★★★★★
          <span
            className="absolute inset-y-0 left-0 overflow-hidden whitespace-nowrap text-[#d79a40]"
            style={{ width: `${rating * 20}%` }}
          >
            ★★★★★
          </span>
        </span>
      )}
      {hasRating && <span className="tabular-nums">{rating.toFixed(1)}</span>}
      <span className="underline decoration-line underline-offset-2">
        Read reviews{!hasRating && ` at ${RETAILER_LABELS[offer.retailer]}`}
      </span>
    </a>
  );
}
import type { Offer } from "@/lib/types";

const STAGES = ["bg-stage-lavender", "bg-stage-blush", "bg-stage-butter"];

/** The same item always gets the same tint, so a list reads as a calm mix rather than a pattern. */
function stageFor(label: string) {
  let hash = 0;
  for (const char of label) hash = (hash * 31 + char.charCodeAt(0)) | 0;
  return STAGES[Math.abs(hash) % STAGES.length];
}

/** A product photo set on a soft tinted stage. Without a photo, a quiet outlined stage names the item instead. */
export function ProductPhoto({ offer, label, className = "" }: { offer?: Offer; label: string; className?: string }) {
  if (!offer?.imageUrl) {
    return (
      <div className={`flex shrink-0 items-center justify-center rounded-[18px] border border-dashed border-line ${className}`}>
        <span className="px-2 text-center font-serif text-[13px] leading-snug text-muted">{label}</span>
      </div>
    );
  }
  return (
    <div className={`stage flex shrink-0 items-center justify-center ${stageFor(label)} ${className}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={offer.imageUrl} alt="" loading="lazy" className="h-full w-full object-contain p-[10%]" />
    </div>
  );
}
